      "content": "{\n  \"name\": \"dsh-cost-meter\",\n  \"version\": \"1.9.41\",\n  \"description\": \"DeepSeek Harness 会话费用统计插件:本会话成本、当日费用、历史记录与官方价格同步,支持多厂商多模型价格计费(内置 170+ 模型 ID 价格目录与自动匹配)、主流 Coding Plan 订阅额度查询与显示(16 家,含 WorkBuddy 官方积分、OpenDesign 工作区查询、含小米 MiMo Token Plan 控制台 Cookie 查询、SCNet Token Plan 本地 Credits 计量与火山方舟 Volcano Ark Coding Plan AK/SK 签名查询)、自定义 Provider 余额查询(可配任意 HTTP 端点)与余额进度条、峰谷计价时段显示与切换前弹窗/系统通知提醒(位置/提前量/类型可配),界面中英双语。Session cost tracking plugin for DeepSeek Harness: per-conversation cost, daily totals, history and official price sync, with multi-vendor model pricing (built-in 170+ model-ID catalog with auto-matching), Coding Plan quota queries & display for 16 vendors (incl. WorkBuddy official credits, OpenDesign workspace queries, Xiaomi MiMo Token Plan via console cookie, local credits metering for the SCNet Token Plan and Volcano Ark Coding Plan via AK/SK signature), plan/API dual-track billing with per-1% & full-window Token Plan usage estimates, custom provider balance lookup (configurable HTTP endpoint) and balance progress bar, plus peak/off-peak pricing display with pre-switch popup & system-notification alerts (position / lead time / type configurable), in a bilingual (Chinese/English) UI.\",\n  \"type\": \"module\",\n  \"main\": \"lib/bootstrap.js\",\n  \"bin\": {\n    \"dsh-cost-meter\": \"./lib/billing-storage-cli.js\",\n    \"dsh-cost-meter-repair-sessions\": \"./lib/repair-sessions-cli.js\"\n  },\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/bootstrap.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./typert\": {\n      \"default\": \"./lib/typert.host.js\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dsh\": \">=0.2.0-rc.1 <0.3.0-0\",\n      \"dshReleases\": {\n        \"0.2.0-rc.1\": \"compatible\",\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-alpha.5\": \"compatible\",\n        \"0.2.1-rc.1\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"dshhub\": {\n    \"schemaVersion\": 1,\n    \"displayName\": \"dsh-cost-meter\",\n    \"summary\": \"DeepSeek Harness 会话费用统计:本会话费用、预算图框、官方余额、自定义 Provider 余额查询、Coding Plan 额度查询、历史记录,支持峰谷计价(切换前弹窗与系统通知提醒)与官方价格一键同步。\",\n    \"categories\": [\n      \"费用\",\n      \"Web UI\",\n      \"观测\"\n    ],\n    \"surfaces\": [\n      \"host\",\n      \"web\"\n    ],\n    \"capabilities\": {\n      \"provides\": [\n        \"service:cost-meter\"\n      ]\n    },\n    \"compatibility\": {\n      \"dsh\": \">=0.2.0-rc.1 <0.3.0-0\",\n      \"node\": \">=20\"\n    },\n    \"permissions\": {\n      \"network\": [\n        \"https://chatgpt.com\",\n        \"https://api.deepseek.com\",\n        \"https://api-docs.deepseek.com\",\n        \"https://open.volcengineapi.com\",\n        \"https://ark.cn-beijing.volces.com\",\n        \"https://opencode.ai\",\n        \"https://api.anthropic.com\",\n        \"https://api.z.ai\",\n        \"https://open.bigmodel.cn\",\n        \"https://www.minimaxi.com\",\n        \"https://www.minimax.cn\",\n        \"https://www.minimax.io\",\n        \"https://api.kimi.com\",\n        \"https://api.moonshot.cn\",\n        \"https://openrouter.ai\",\n        \"https://api.siliconflow.cn\",\n        \"https://api.commandcode.ai\",\n        \"https://api.cline.bot\",\n        \"https://api.factory.ai\",\n        \"https://ax.ac.sugon.com\",\n        \"https://platform.qianwenai.com\",\n        \"https://platform-home.qianwenai.com\",\n        \"https://business.aliyuncs.com\",\n        \"https://tokenrhythm.studio\",\n        \"https://platform.xiaomimimo.com\",\n        \"https://console.bce.baidu.com\",\n        \"https://www.codebuddy.cn\",\n        \"https://www.workbuddy.ai\",\n        \"https://amr-api.open-design.ai\",\n        \"https://api.frankfurter.dev\"\n      ]\n    }\n  },\n  \"files\": [\n    \"docs/web-request-fees.md\",\n    \"locale\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"docs/provider-pricing.json\",\n    \"docs/billing-statistics.md\",\n    \"docs/billion-context-billing.md\",\n    \"docs/opendesign-billing.md\",\n    \"docs/custom-balance-sources.md\",\n    \"docs/performance-2026-10-18.md\",\n    \"docs/performance-2026-10-18.json\",\n    \"docs/update-notes-2026-10-15.md\",\n    \"docs/ledger-lock-recovery.md\",\n    \"docs/external-usage.md\",\n    \"docs/qwen-cli-quota.md\",\n    \"docs/factory-quota.md\",\n    \"docs/baidu-token-plan.md\",\n    \"docs/session-sidebar-recovery.md\",\n    \"docs/provider-pricing-2026-10.md\",\n    \"docs/openrouter-prices.md\",\n    \"docs/context-costs-design.md\",\n    \"docs/context-costs-preview.png\",\n    \"docs/cost-share-overview.png\",\n    \"docs/call-detail-preview.png\",\n    \"docs/step-billing-preview.png\",\n    \"docs/maintenance-review-2026-10-10.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"docs/display-settings.md\",\n    \"docs/update-notes-1.8.28.md\",\n    \"docs/update-notes-1.8.29.md\",\n    \"docs/context-stream-diagnostics.md\",\n    \"docs/exchange-rates.md\",\n    \"docs/update-notes-1.8.30.md\",\n    \"docs/idle-performance.md\",\n    \"docs/pricing-history-storage.md\",\n    \"docs/custom-model-prices.md\",\n    \"docs/update-notes-1.8.31.md\",\n    \"docs/update-notes-1.8.32.md\",\n    \"docs/update-notes-1.8.33.md\",\n    \"docs/update-notes-1.8.34.md\",\n    \"docs/update-notes-1.8.35.md\",\n    \"docs/update-notes-1.8.36.md\",\n    \"docs/update-notes-1.9.0.md\",\n    \"docs/update-notes-1.9.1.md\",\n    \"docs/update-notes-1.9.2.md\",\n    \"docs/better-session.md\",\n    \"docs/model-history-repricing.md\",\n    \"docs/tokenrhythm-balance.md\",\n    \"docs/dsh-0.2.1-compatibility.md\",\n    \"docs/pnpm-supply-chain-policy.md\",\n    \"docs/update-notes-1.9.3.md\",\n    \"docs/update-notes-1.9.4.md\",\n    \"docs/update-notes-1.9.5.md\",\n    \"docs/update-notes-1.9.6.md\",\n    \"docs/update-notes-1.9.7.md\",\n    \"docs/update-notes-1.9.8.md\",\n    \"docs/update-notes-1.9.9.md\",\n    \"docs/plugin-compatibility-watch.md\",\n    \"docs/update-notes-1.9.10.md\",\n    \"docs/update-notes-1.9.11.md\",\n    \"docs/update-notes-1.9.12.md\",\n    \"docs/update-notes-1.9.13.md\",\n    \"docs/update-notes-1.9.14.md\",\n    \"docs/update-notes-1.9.15.md\",\n    \"docs/update-notes-1.9.16.md\",\n    \"docs/update-notes-1.9.17.md\",\n    \"docs/update-notes-1.9.18.md\",\n    \"docs/update-notes-1.9.19.md\",\n    \"docs/update-notes-1.9.20.md\",\n    \"docs/update-notes-1.9.21.md\",\n    \"docs/update-notes-1.9.22.md\",\n    \"docs/update-notes-1.9.23.md\",\n    \"docs/update-notes-1.9.24.md\",\n    \"docs/update-notes-1.9.25.md\",\n    \"docs/update-notes-1.9.26.md\",\n    \"docs/update-notes-1.9.27.md\",\n    \"docs/update-notes-1.9.28.md\",\n    \"docs/update-notes-1.9.29.md\",\n    \"docs/update-notes-1.9.30.md\",\n    \"docs/settings-pages.md\",\n    \"docs/update-notes-1.9.31.md\",\n    \"docs/update-notes-1.9.32.md\",\n    \"docs/update-notes-1.9.33.md\",\n    \"docs/billing-storage.md\",\n    \"docs/update-notes-1.9.34.md\",\n    \"docs/update-notes-1.9.35.md\",\n    \"docs/update-notes-1.9.36.md\",\n    \"docs/update-notes-1.9.37.md\",\n    \"docs/update-notes-1.9.38.md\",\n    \"docs/update-notes-1.9.39.md\",\n    \"docs/update-notes-1.9.40.md\",\n    \"docs/update-notes-1.9.41.md\"\n  ],\n  \"dependencies\": {\n    \"acorn\": \"8.15.0\",\n    \"zod\": \"4.6.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-credentials\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.3.0-0\",\n    \"@deepseek-ai/dsh-home-paths\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.3.0-0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Han-1413141/dsh-cost-meter.git\"\n  },\n  \"homepage\": \"https://github.com/Han-1413