      "path": "lib/billing-stream.js",
      "content": "/**\n * llm/stream 计费包裹(issue #48 包装路由重复计费修复)。\n *\n * 宿主的 `llm/stream` 是一条监听器瀑布:每次 ctx.llm.stream() 都会把全部\n * 监听器按注册序串起来。modlens / vision-router 这类包装路由插件的适配器\n * 在自己 stream() 体内再次调用 ctx.llm.stream({ ..., provider: upstream })\n * ——于是同一次请求沿 `wrapper-vision → wrapper → official` 每层都完整走\n * 一遍瀑布,链尾的计费监听器每层都把 usage 记进账本(同 token 逐位相同 ×3)。\n *\n * 修复:用 AsyncLocalStorage 标记「正在计费消费的流」。外层计费包装在标记\n * 内拉取下游 chunk;下游适配器体内再发起的 ctx.llm.stream() 在同一异步上\n * 下文中同步分发瀑布,内层计费监听器读到标记即判定为嵌套调用,直接透传\n * next() 不再包一层(也就不再记账)。usage 只由最外层记一次。\n *\n * ALS 按异步上下文隔离:两个并发请求各自从无标记的根上下文进入,互不误伤。\n */\n\nimport { AsyncLocalStorage } from 'node:async_hooks'\n\n/**\n * 嵌套深度标记:值恒为 1(存在即嵌套);按异步上下文隔离,并发流互不串扰。\n *\n * 设计边界(R-7):恒定深度标记会把「外层 pull 的异步上下文内同步分发瀑布时」\n * 发起的任何 ctx.llm.stream() 一律判定为已记账的嵌套调用。单层包装链\n * (issue #48 目标:适配器在自己 stream() 体内恰好发起一次上游调用)语义正确;\n * 若未来出现扇出型路由——单次 pull 内派生 >1 条上游流——第二条及之后的上游\n * 将被误判为嵌套而漏记。出现此类路由时需改用按流实例区分的标记身份。\n */\nconst llmStreamDepth = new AsyncLocalStorage()\n\n/**\n * 创建 llm/stream 计费监听器。\n * @param {object} deps\n * @param {(usage: object, model: string, sessionId: string, atMs: number, provider: string) => void} deps.account\n *   计费回调:流结束时以捕获的 usage 块调用(五参签名与 ledger.account 对齐,\n *   由 index.js 负责把 usage 五桶映射过去;atMs 为请求发起时刻,见下)。\n * @param {() => number} [deps.now] - 时钟源(默认 Date.now),测试注入用。\n * @returns {(options: object, next: () => AsyncIterable) => AsyncIterable} 宿主监听器。\n */\nexport function createLlmStreamBilling({ account, now = Date.now, bridge, activity }) {\n  return (options, next) => {\n    const downstream = next()\n    // 嵌套内层(包装路由在上层计费流的消费上下文中再发起的 llm/stream):\n    // 外层已记账,透传下游流,不再包裹。\n    if (llmStreamDepth.getStore() !== undefined) return downstream\n    // 峰谷档位按「请求发起」时刻判定:一次流式调用可能跨峰谷边界整点,\n    // 按完成时刻归档会把数分钟前发起的请求算进另一个峰位(官方口径为\n    // 请求侧计时;实测跨点分歧可达分毛级)。瀑布分发即请求发起时刻。\n    const startedAtMs = now()\n    const proxy = bridge?.createScope(options, startedAtMs)\n    return (async function* costMeterStream() {\n      let usage = null\n      const release = activity?.enter(options?.sessionId)\n      let iterator\n      let completed = false\n      try {\n        iterator = downstream[Symbol.asyncIterator]()\n        for (;;) {\n          // 在深度标记内拉取下游:下游适配器(modlens 等)体内再发起的\n          // ctx.llm.stream() 同步瀑布分发继承 depth=1,其监听器判定为嵌套。\n          const result = await llmStreamDepth.run(1, () => proxy ? proxy.run(() => iterator.next()) : iterator.next())\n          if (result.done) break\n          const chunk = result.value\n          if (chunk !== null && chunk !== undefined && chunk.type === 'usage' && chunk.usage != null) {\n            usage = chunk.usage\n            proxy?.observe(usage)\n          }\n          yield chunk\n        }\n        completed = true\n      } catch (error) {\n        // Names only: messages, headers and request contents may contain secrets.\n        const name = /^[A-Za-z][A-Za-z0-9]{0,63}$/.test(error?.name) ? error.name : 'Error'\n        console.warn(`[dsh-cost-meter] stream interrupted (${name}); context measurement deferred during generation`)\n        throw error\n      } finally {\n        // 手写 for(;;) 不具备 for-await 的自动关闭语义:消费方提前中断(break/\n        // return/throw)时必须显式向下游传播 return(),否则上游 HTTP 流会继续\n        // 跑完(供应商照常计满 token,usage 块却无人读取),socket 悬挂泄漏。\n        if (!completed) {\n          try {\n            await iterator?.return?.()\n          } catch {}\n        }\n        release?.()\n        const covered = proxy ? await proxy.finish(usage) : false\n        if (usage !== null && !covered) {\n          try {\n            account(usage, options?.model, options?.sessionId, startedAtMs, options?.provider)\n          } catch (error) {\n            console.warn(`[dsh-cost-meter] 计费失败: ${String(error)}`)\n          }\n        }\n      }\n    })()\n  }\n}\n"
    },
    {
      "path": "lib/store.js",
      "content": "/**\n * 账本存储:每日聚合、会话聚合、配置持久化($DSH_HOME/storages/cost-meter/ledger.json)。\n *\n * 所有金额字段均为美元;币种换算只发生在展示层。写入采用临时文件 +\n * 原子重命名,并做防抖;账本按 config.historyDays 保留最近 N 天。\n */\n\nimport { FX_FIELDS, frozenAmounts, frozenFields, addFrozen, freezeLegacyAmounts, fxRatesOf } from './exchange-rates.js'\nimport { normalizeQueryAccounts, validQueryAccounts } from './query-accounts.js'\nimport { normalizeModelStatistics, validModelStatistics } from './model-statistics.js'\nimport { readFileSync, renameSync, statSync } from 'node:fs'\nimport { randomUUID } from 'node:crypto'\nimport { matchesRequestFeeModel, validRequestFee } from './web-request-pricing.js'\nimport { repairDailySessionTotals } from './ledger-totals.js'\nimport { startLedgerWrite } from './ledger-writer.js'\nimport { withLedgerLock, readLedger, writeLedger, readLedgerConfigBackup, writeLedgerConfigBackup, applyAccount, mergeLedger, mergeRuntimeConfig, cleanUsageCursors, cleanWriteReceipts, cloneLedgerSnapshot } from './ledger-persistence.js'\nimport { normalizePricingHistory, advancePricingHistory, bindPricingHistory, pricingConfigAt } from './billing-history.js'\nimport { join } from 'node:path'\nimport { resolveDshHome } from '@deepseek-ai/dsh-home-paths'\nimport {\n  DEFAULT_PEAK_EFFECTIVE_AT,\n  DEFAULT_PEAK_WINDOWS,\n  DEFAULT_PEAK_HOLIDAYS,\n  DEFAULT_PRICE_TABLE,\n  DEFAULT_PRICE_TABLE_CNY,\n  DEFAULT_PROVIDER_PRICE_TABLE,\n  upgradeProviderPriceDefaults,\n  upgradeProviderPriceCatalog20261015,\n  upgradeStepfunPriceCatalog,\n  costOf,\n  normalizePrice,\n  priceEntryFor,\n  providerPriceEntryFor,\n  normalizeCustomPrice,\n  usdFromCost,\n  isWrapperProviderId,\n  wrapperUpstreamProvider,\n  isLocalOriginProviderOrModel,\n} from './pricing.js'\nimport { CODING_PLAN_PROVIDER_IDS, normalizeMiniMaxBaseUrl } from './coding-plans.js'\nimport { normalizeFactoryOrgId } from './factory-quota.js'\nimport { normalizeOpenDesignWorkspace } from './opendesign.js'\nimport { validWorkBuddyAccountId } from './workbuddy-accounts.js'\nimport { DEFAULT_PLAN_PROVIDER_CLASS, PLAN_PROVIDER_IDS, billingClassOf, enabledPlanSetOf, planProviderIdOf, convertRecentCallsToBuckets, isRoutedThirdPartyCall } from './plan-billing.js'\n\nconst LEDGER_VERSION = 1\nconst DEFAULT_HISTORY_DAYS = 180\nfunction dashboardUrlOf(value) {\n  if (typeof value !== 'string' || value.length > 2048 || !/^https?:\\/\\//i.test(value.trim())) return ''\n  try {\n    const url = new URL(value.trim())\n    return url.username || url.password ? '' : url.href\n  } catch { return '' }\n}\nfunction diskRevisionOf(path) {\n  try { const info = statSync(path, { bigint: true }); return `${info.ino}:${info.mtimeNs}:${info.size}` }\n  catch (error) { if (error.code === 'ENOENT') return null; throw error }\n}\nconst GATEWAY_PROVIDER_IDS = ['antigravity', 'claude', 'codex', 'kimi', 'xai', 'workbuddy']\nconst GATEWAY_DISPLAY_VALUES = ['sidebar', 'settings', 'both', 'off']\nconst GATEWAY_SOURCE_ID_RE = /^[a-z0-9][a-z0-9_-]{0,47}$/\nconst GATEWAY_SECRET_KEYS = ['managementKey', 'apiKey', 'key', 'token', 'accessToken', 'oauthToken', 'secret', 'secretKey', 'password']\n\nfunction canonicalGatewayProviderForStore(value) {\n  const provider = typeof value === 'string' ? value.trim().toLowerCase() : value\n  return provider === 'anthropic' ? 'claude' : provider\n}\n\nfunction gatewayPortIsValid(port) {\n  if (port === undefined) return true\n  const number = Number(port)\n  return /^\\d{1,5}$/.test(port) && number >= 1 && number <= 65535\n}\n\n/** Exact host[:port] allowlist entry; wildcards, paths, credentials and bare IPv6 are rejected. */\nfunction gatewayAllowedHostIsValid(raw) {\n  if (typeof raw !== 'string') return false\n  const value = raw.trim().toLowerCase()\n  if (value.length === 0 || value !== raw.trim() || /[\\s/?#@\\\\]/.test(value)) return false\n  if (value.startsWith('[')) {\n    const close = value.indexOf(']')\n    if (close < 0) return false\n    const host = value.slice(1, close)\n    const port = value.slice(close + 1)\n    if (!host.includes(':') || !/^[0-9a-f:.]+$/.test(host)) return false\n    return port === '' || (port.startsWith(':') && gatewayPortIsValid(port.slice(1)))\n  }\n  const portMatch = value.match(/^(.*?)(?::(\\d{1,5}))?$/)\n  if (portMatch === null || !gatewayPortIsValid(portMatch[2])) return false\n  const host = portMatch[1]\n  const octets = host.match(/^(\\d+)\\.(\\d+)\\.(\\d+)\\.(\\d+)$/)\n  if (octets !== null) return octets.slice(1).every(part => Number(part) >= 0 && Number(part) <= 255)\n  return /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))*$/.test(host)\n}\n\nfunction stripGatewaySourceSecrets(source) {\n  if (source === null || typeof source !== 'object' || Array.isArray(source)) return source\n  const copy = { ...source }\n  for (const key of GATEWAY_SECRET_KEYS) delete copy[key]\n  return copy\n}\n\nfunction normalizeGatewaySourceForStore(raw, fallback = {}) {\n  const source = raw !== null && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}\n  const id = typeof source.id === 'string' ? source.id.trim() : (typeof fallback.id === 'string' ? fallback.id : '')\n  const providers = Array.isArray(source.includeProviders)\n    ? [...new Set(source.includeProviders.filter(value => typeof value === 'string').map(value => canonicalGatewayProviderForStore(value)).filter(value => GATEWAY_PROVIDER_IDS.includes(value)))]\n    : GATEWAY_PROVIDER_IDS.slice()\n  const hosts = Array.isArray(source.allowedHosts)\n    ? [...new Set(source.allowedHosts.filter(value => gatewayAllowedHostIsValid(value)).map(value => value.trim().toLowerCase()))].slice(0, 16)\n    : []\n  const refresh = Number(source.refreshMinutes)\n  return {\n    id,\n    type: typeof source.type === 'string' ? source.type : 'cliproxyapi',\n    label: typeof source.label === 'string' ? source.label.slice(0, 80) : (typeof fallback.label === 'string' ? fallback.label : id),\n    baseURL: typeof source.baseURL === 'string' ? source.baseURL.trim().replace(/\\/+$/, '') : '',\n    enabled: source.enabled !== false,\n    display: GATEWAY_DISPLAY_VALUES.includes(source.display) ? source.display : 'both',\n    refreshMinutes: Number.isInteger(refresh) ? Math.min(1440, Math.max(1, refresh)) : 15,\n    includeProviders: providers.length > 0 ? providers : GATEWAY_PROVIDER_IDS.slice(),\n    allowedHosts: hosts,\n    allowInsecureHttp: source.allowInsecureHttp === true,\n    antigravityOnlyGemini: source.antigravityOnlyGemini === true,\n  }\n}\n\nfunction gatewayOriginIsValid(value) {\n  try {\n    const url = new URL(value)\n    return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password\n      && !url.search && !url.hash && url.pathname === '/'\n  } catch { return false }\n}\n\nfunction gatewayHostIsLoopback(value) {\n  try {\n    const host = new URL(value).hostname.toLowerCase()\n    return host === 'localhost' || host === '::1' || /^127(?:\\.\\d{1,3}){3}$/.test(host)\n  } catch { return false }\n}\n\n/** 默认配置(首次启动;之后持久化副本优先)。 */\nexport function defaultConfig() {\n  return {\n    queryAccounts: {},\n    locale: 'auto', // 界面语言:auto(跟随浏览器) | zh(中文) | en(English)\n    position: 'dock', // 会话费用显示位置:dock(输入区下方) | header(会话标题栏) | off\n    sidebar: true, // 侧边栏底部显示当日费用\n    currency: 'CNY', // CNY | USD | EUR | custom\n    symbol: '¥',\n    decimals: 4,\n    exchangeRateAuto: true,\n    fxRates: { USD: 1, CNY: 7.2, EUR: 0.92 },\n    exchangeRateCheckedAt: 0,\n    exchangeRateDate: '',\n    exchangeRate: 7.2, // 展示层:美元 → 币种汇率\n    pricingCurrency: 'USD', // 官方价格币种(issue #47):USD(美元官方价) | CNY(人民币官方价,计费按汇率折算入账)\n    peakEnabled: true, // 启用峰谷计价\n    peakEffectiveAt: DEFAULT_PEAK_EFFECTIVE_AT,\n    peakWindows: DEFAULT_PEAK_WINDOWS.map(w => ({ ...w })),\n    peakHolidays: [...DEFAULT_PEAK_HOLIDAYS], // 北京日历日；调休上班的周末仍按全天谷价\n    peakNotice: true, // 峰时高价时段显著提示(侧边栏预算框/今日费用/设置页预算面板)\n    peakAlertEnabled: true, // 峰/谷切换前弹窗提醒(全局浮层)\n    peakAlertAhead: 2, // 提前提醒量(分钟,1-30)\n    peakAlertTarget: 'both', // 提醒类型:peak(进入峰) | offpeak(进入谷) | both(峰和谷)\n    peakAlertPosition: 'corner', // 弹窗位置:corner(右下角) | center(屏幕中心)\n    peakAlertWebNotify: false, // 弹窗时额外发浏览器(系统)通知,需用户在地址栏授权\n    showSessionId: false, // 会话列表中附显会话 ID(默认只显示标题,需要时开启)\n    sessionListCosts: false,\n    sessionListCostPeriod: 'total',\n    hideOfficialBalance: false, // 隐藏官方账户余额(issue #45):开启后侧边栏/会话页/设置页的官方余额 UI 整体不渲染\n    hideBudget: false, // Hide the sidebar budget card without disabling budget tracking.\n    hideTodayCost: false, // 隐藏今日消耗金额(issue #46):开启后侧栏今日费用行/预算明细今日行/概览今日卡片不渲染\n    modelStatistics: {}, // Per channel/model: today, monthly/all-time summaries and budgets.\n    hideSessionCostHeader: false,\n    hideSessionCostDock: false,\n    hideTurnCost: false,\n    sessionCostCompact: false, // 输入区下方会话费用行只显示金额(悬停 title 与费用明细弹窗保留完整分项)\n    followSkinTransparency: false, // 跟随皮肤透明度；默认保留不透明遮挡面。\n    contextCostsEnabled: false,\n    contextCostsPromptSeen: false,\n    statisticsBasis: 'auto', // 未选择时沿用全局 API / 含 Plan 口径。\n    sidebarTodayMetric: 'cost',\n    sidebarTodayBalanceInline: false,\n    sidebarOrder: [], // 侧栏组件顺序；未设置时沿用原布局。\n    showTotalWithPlan: false, // 「含 Plan 总额」全局开关(v1.6.0):开启后全部金额展示按总等值(cost)计;默认按真金白银(apiCost)\n    includeSubagentCost: false, // 本会话展示可合并连续子代理后代;不重复写入每日账本。\n    codexQuotaEnabled: false, // Codex 额度按需开启,避免未使用 Codex 时显示卡片或查询。\n    codexQuotaSidebar: true, // 独立控制侧栏卡片，保留会话额度条。\n    codexQuotaStrip: true, // 独立控制输入区额度条，旧配置保留原显示。\n    codexQuotaSource: 'auto', // Codex 额度数据源:auto | connect | subscription | chatgpt | pi-ai | chatgpt-sub。\n    // dsh-codex-subscription 兼容:一次性历史归类提示是否已永久关闭 / 历史归类完成时刻 ms(0 = 未应用)。\n    codexCompatPromptDismissed: false,\n    codexCompatHistoryAppliedAt: 0,\n    sidebarSimple: false,\n    sidebarSimplePromptSeen: false,\n    sidebarModels: { enabled: false, period: 'today', topN: 5, summary: 'total', position: 'last', defaultOpen: false, remember: true, tokens: false, shares: true, refreshSeconds: 60, dock: false },\n    sidebarSummaryPromptSeen: false,\n    billionContextNoticeEnabled: true,\n    billionContextNoticesSeen: [],\n    billingStorageRetentionDays: 7,\n    sidebarStyle: 'standard', // 侧边栏进度条样式:standard(标准,纵向单列) | compact(紧凑,额度卡两列网格)\n    legacyAutoImportedAt: 0, // 安装前历史自动导入标记(issue #27):完成时刻 ms;0 = 尚未跑过\n    peakStyle: 'compact', // compact / classic 保留原样；progress 按侧栏布局显示时间进度。\n    peakTimeDisplay: 'both', // both / countdown / switch\n    peakProgressPromptSeen: false,\n    priceMatch: 'auto', // 未知模型名自动匹配价格表:auto(归一化/安全后缀) | exact(仅精确)\n    priceMatchDismissed: [], // 从匹配设置中移除的 provider:model 行；不删除用量或改变计价规则。\n    priceOverrides: {}, // 手动匹配覆盖:{ 'provider:modelId': 'provider:模型 | deepseek:__default__' };裸模型名 = 同渠道换名(旧版遗留,跨渠道裸 DeepSeek 名由查价兜底自愈,issue #56)\n    priceTableDisplay: {}, // 费用设置直接显示(按模型):键 'provider:modelId' → 布尔;缺省 = DeepSeek 模型直接显示、第三方收入拓展价格表(含 DeepSeek 模型也可逐模型收入)\n    prices: {\n      models: Object.fromEntries(\n        Object.entries(DEFAULT_PRICE_TABLE.models).map(([id, entry]) => [id, structuredClone(entry)]),\n      ),\n      default: structuredClone(DEFAULT_PRICE_TABLE.default),\n       providers: Object.fromEntries(\n        Object.entries(DEFAULT_PROVIDER_PRICE_TABLE).map(([provider, table]) => [provider, {\n          models: Object.fromEntries(Object.entries(table.models).map(([id, entry]) => [id, structuredClone(entry)])),\n        }]),\n      ),\n    },\n    budget: {\n      enabled: false, // 启用预算\n      amount: 100, // 预算额度(按显示币种)\n      period: 'month', // day(今日) | month(本月) | all(累计) | custom(自定义区间)\n      customStart: null, // custom 周期开始日期(YYYY-MM-DD)\n      customEnd: null, // custom 周期结束日期(YYYY-MM-DD,空 = 今日)\n      detail: true, // 预算图框详细信息:今日费用与占预算% + 已用/额度行\n    },\n    codingPlans: {\n      opendesign: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '', workspaceId: '' },\n      factory: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '', orgId: '', factoryPool: 'standard' },\n      // 各家 coding plan 额度查询(默认关闭;开启后按 Key 发现链查询并在设置页展示)。\n      anthropic: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      zai: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      // MiniMax 自引入起即是「启用即在侧边栏展示 5h/7d 卡片」,显示位置配置落地后默认 both 保持该惯例;\n      // 其余厂商默认 settings(仅设置页),按需在设置页切换(issue #31)。\n      minimax: { enabled: false, display: 'both', refreshMinutes: 15, apiKey: '', baseUrl: '' },\n      kimi: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      openrouter: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      siliconflow: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      commandcode: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      clinepass: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '' },\n      // SCNet Token Plan 无 API 额度端点:按官方 Credits 抵扣表本地估算(issue #26)。\n      // planCredits=月度 Credits 额度;planStart=订阅起始日(空 = 自然月)。\n      scnet: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '', planCredits: 240000, planStart: '' },\n      qwen: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '', quotaSource: 'local', planCredits: 500000, planStart: '', rates: {} },\n      // 火山方舟 Volcano Ark Coding Plan(issue #60):管控面 AK/SK+HMAC,三窗口(5h/weekly/monthly)\n      volcengine: { enabled: false, display: 'settings', refreshMinutes: 15, apiKey: '', accessKeyId: '', secretAccessKey: '' },\n    },\n    balance: {\n      display: 'both', // 余额显示位置:sidebar(主页面侧边栏) | settings(设置页) | both | off\n      refreshMinutes: 5, // 余额自动刷新间隔(分钟)\n      showProgressBar: false, // 全局:侧边栏余额以三段进度条展示(蓝=余额,橙=当日,灰=已用)\n      showSource: false,\n      officialChannelOnly: false,\n      budgetCap: null, // 可选:手动额度上限;留空则优先用 API 返回的 max_budget;仍无则整条蓝色\n      reconcile: true, // 余额差交叉校验:官方余额当日变动与本地账本今日合计偏差超阈值时提示\n      clickHintSeen: false, // 更新后提醒:余额图框点击刷新的引导是否已处理(issue #37)\n    },\n    go