ndingWrite = generation !== this.writeGeneration || remaining.length > 0 || remainingRepairs.length > 0\n        this.legacyPricingHistory = false\n        this.diskRevision = result.revision\n        if (this.pendingWrite && !this.closed) this.scheduleWrite()\n      })\n      return this.backgroundWrite.promise\n    } catch (error) {\n      this.fallbackWrite(error)\n      return Promise.resolve()\n    }\n  }\n\n  /** 停止后续写入并最终落盘(插件卸载/进程退出)。 */\n  close() {\n    // Keep the main loop running so worker completion/error events can reach\n    // Cordis while it awaits disposal. A synchronous join blocks those events.\n    if (this.backgroundWrite) return this.backgroundWrite.promise.then(() => this.close())\n    this.flush(5000)              // 退出时保留同步最终提交；日常写入遇锁立即让出并重试。\n    this.closed = true\n    if (this.writeTimer !== null) { clearTimeout(this.writeTimer); this.writeTimer = null }\n  }\n\n  /** 聚合某前缀(如 '2026-08')的全部天。 */\n  sumDays(prefix) {\n    const total = zeroDay(prefix === undefined ? 'total' : prefix)\n    for (const [date, day] of Object.entries(this.days)) {\n      if (prefix !== undefined && !date.startsWith(prefix)) continue\n      total.input += day.input ?? 0\n      total.output += day.output ?? 0\n      total.cacheRead += day.cacheRead ?? 0\n      total.cacheWrite += day.cacheWrite ?? 0\n      total.reasoning += day.reasoning ?? 0\n      total.calls += day.calls ?? 0\n      addFrozen(total, day)\n      total.cost += day.cost ?? 0\n      total.apiCost = (total.apiCost ?? 0) + (day.apiCost ?? day.cost ?? 0)\n      for (const [key, value] of Object.entries(day.byProviderModel ?? {})) {\n        const current = total.byProviderModel[key] ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0, calls: 0, cost: 0, apiCost: 0 }\n        total.byProviderModel[key] = {\n          ...addFrozen({ ...frozenFields(current) }, value),\n          input: current.input + (value.input ?? 0), output: current.output + (value.output ?? 0),\n          cacheRead: current.cacheRead + (value.cacheRead ?? 0), cacheWrite: current.cacheWrite + (value.cacheWrite ?? 0),\n          reasoning: current.reasoning + (value.reasoning ?? 0),\n          calls: current.calls + (value.calls ?? 0), cost: current.cost + (value.cost ?? 0),\n          apiCost: (current.apiCost ?? 0) + (value.apiCost ?? value.cost ?? 0),\n        }\n      }\n    }\n    total.date = prefix === undefined ? 'total' : prefix\n    return total\n  }\n\n  /**\n   * 聚合自定义日期区间 [startKey, endKey](含两端,YYYY-MM-DD 字典序)。\n   * @param startKey - 起始日期键。\n   * @param endKey - 结束日期键。\n   * @returns 区间聚合(仅数字字段,date 为区间键)。\n   */\n  sumRange(startKey, endKey) {\n    const total = zeroDay(`${startKey}..${endKey}`)\n    if (typeof startKey !== 'string' || typeof endKey !== 'string') return total\n    for (const [date, day] of Object.entries(this.days)) {\n      if (date < startKey || date > endKey) continue\n      total.input += day.input ?? 0\n      total.output += day.output ?? 0\n      total.cacheRead += day.cacheRead ?? 0\n      total.cacheWrite += day.cacheWrite ?? 0\n      total.reasoning += day.reasoning ?? 0\n      total.calls += day.calls ?? 0\n      addFrozen(total, day)\n      total.cost += day.cost ?? 0\n      total.apiCost = (total.apiCost ?? 0) + (day.apiCost ?? day.cost ?? 0)\n      for (const [key, value] of Object.entries(day.byProviderModel ?? {})) {\n        const current = total.byProviderModel[key] ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0, calls: 0, cost: 0, apiCost: 0 }\n        total.byProviderModel[key] = {\n          ...addFrozen({ ...frozenFields(current) }, value),\n          input: current.input + (value.input ?? 0), output: current.output + (value.output ?? 0),\n          cacheRead: current.cacheRead + (value.cacheRead ?? 0), cacheWrite: current.cacheWrite + (value.cacheWrite ?? 0),\n          reasoning: current.reasoning + (value.reasoning ?? 0),\n          calls: current.calls + (value.calls ?? 0), cost: current.cost + (value.cost ?? 0),\n          apiCost: (current.apiCost ?? 0) + (value.apiCost ?? value.cost ?? 0),\n        }\n      }\n    }\n    return total\n  }\n\n  /** 今日记录(可能为空)。 */\n  today() {\n    const date = localDayKey(Date.now())\n    const day = this.days[date]\n    return day === undefined ? zeroDay(date) : this.copyDay(day)\n  }\n\n  /**\n   * 今日账本中归属 DeepSeek 官方渠道的费用(USD,issue #36)。\n   * 官方余额进度条「当日已用」与余额差对账只关心会扣 DeepSeek 开放平台余额的调用;\n   * Coding Plan、自定义 Provider 等渠道的费用不计入(各自额度条/余额条自行体现)。\n   */\n  todayOfficialCost() {\n    return officialCostOfDay(this.days[localDayKey(Date.now())])\n  }\n\n  /** 历史列表(降序,轻量副本,不含会话明细)。 */\n  history(limit = 60) {\n    return Object.keys(this.days)\n      .sort()\n      .reverse()\n      .slice(0, limit)\n      .map(date => this.copyDay(this.days[date], true))\n  }\n\n  copyDay(day, withoutSessions = false) {\n    const sessions = withoutSessions || !Array.isArray(day.sessions)\n      ? []\n      : day.sessions.slice().sort((a, b) => b.cost - a.cost).map(s => ({ ...s }))\n    return {\n      ...frozenFields(day),\n      date: String(day.date),\n      input: day.input ?? 0,\n      output: day.output ?? 0,\n      cacheRead: day.cacheRead ?? 0,\n      cacheWrite: day.cacheWrite ?? 0,\n      reasoning: day.reasoning ?? 0,\n      calls: day.calls ?? 0,\n      cost: day.cost ?? 0,\n      apiCost: day.apiCost ?? day.cost ?? 0,\n      byProviderModel: day.byProviderModel ?? {},\n      sessions,\n    }\n  }\n}\n\n// 赠送余额部分减少(issue #302)的保守阈值:同期本地官方渠道费用最多只能解释减量的\n// 1/4,其余至少 3/4 无法由消费解释时,才降级为「赠送余额到期/回收」提示;超过 1/4\n// 仍按既有 drift 处理,避免把真实漏记的消费一并吞掉。与既有漂移阈值\n// (max($0.3, 15%))一样属于内部判定常数;用户侧仍可用 balance.reconcile 关闭整套对账。\nconst GRANTED_RELEASE_MAX_LOCAL_RATIO = 0.25\n\n/**\n * 余额差交叉校验(issue #18 讨论):用官方余额当日变动反推消费,与本地账本今日合计比对。\n * 仅当余额确实减少时才对账——订阅/Coding Plan 消费不动官方余额,若强行用余额差\n * 替代今日费用会把订阅用户全天消费归零;充值/额度结构变动时重置参考点防误判;\n * 参考点与本次拉取的币种不一致时(多币种条目挑选切换/旧账本无币种标记)同样重置。\n * 币种折算(用户实测:CNY 余额账号恒报 drift):余额差按 snap.currency 计价(开放平台\n * 主币种为 ¥),而账本金额恒为 USD——直接相减/比阈值是跨币种错配。折算入 USD 后再比;\n * CNY 折算率取 options.exchangeRate(非法回落 7.2 默认展示汇率),非 CNY 按 1:1。\n * @param prevRef - 上一参考点({ date, total, granted, topped, currency, at })或 null。\n * @param balance - 本次拉取结果({ currency, totalBalance, grantedBalance, toppedUpBalance })。\n * @param todayCost - 本地账本今日合计费用(USD)。\n * @param dayKey - 本地日期键(YYYY-MM-DD)。\n * @param nowMs - 当前时刻。\n * @param [options] - { exchangeRate }:CNY→USD 折算率(1 USD 兑 X CNY)。\n * @returns {{ ref, event }} event.kind ∈ baseline | structure-reset | flat | ok | drift | granted-release;\n *   event.todayCost 是自基准以来的费用增量。granted-release 表示减量可归因于赠送余额\n *   到期/回收(issue #302),ref 已重置为当前快照,调用方按「非消费提示」展示。\n */\nexport function reconcileBalanceDelta(prevRef, balance, todayCost, dayKey, nowMs, options) {\n  if (balance === null || typeof balance !== 'object' || !Number.isFinite(balance.totalBalance)) {\n    return { ref: prevRef ?? null, event: null }\n  }\n  if (!Number.isFinite(todayCost) || todayCost < 0) return { ref: null, event: null }\n  const snap = {\n    date: dayKey,\n    total: balance.totalBalance,\n    granted: Number.isFinite(balance.grantedBalance) ? balance.grantedBalance : 0,\n    topped: Number.isFinite(balance.toppedUpBalance) ? balance.toppedUpBalance : 0,\n    currency: typeof balance.currency === 'string' ? balance.currency : '',\n    at: nowMs,\n    ledgerCost: todayCost,\n  }\n  // 新的一天(或首次/参考点形状异常):打基准,不对账。\n  if (prevRef === null || typeof prevRef !== 'object' || prevRef.date !== dayKey) {\n    return { ref: snap, event: { kind: 'baseline' } }\n  }\n  // 币种变化(#24/#25):选中的条目币种切换(或旧参考点无币种标记)时金额不可比,\n  // 重置基准不对账——否则 USD 0.00 误读会让余额差虚高,触发 drift 误报。\n  if (prevRef.currency !== snap.currency) {\n    return { ref: snap, event: { kind: 'structure-reset' } }\n  }\n  // Legacy references and a cleared/repriced ledger cannot define a comparable interval.\n  if (!Number.isFinite(prevRef.ledgerCost) || prevRef.ledgerCost < 0 || todayCost < prevRef.ledgerCost) {\n    return { ref: snap, event: { kind: 'structure-reset' } }\n  }\n  // 充值/额度授予变动:充值与授信只会让分项余额增加(消费只会减少),分项变大则旧参考点失效,重置不告警。\n  if (snap.granted > prevRef.granted + 0.009 || snap.topped > prevRef.topped + 0.009) {\n    return { ref: snap, event: { kind: 'structure-reset' } }\n  }\n  // 赠送余额当日过期(issue #89):基准时有赠送余额、当前已归零(granted > 0 → ~0),\n  // total 的当日减量里混入了整块赠送失效——这部分不是消费,与账本今日费用必然对不上,\n  // 金额越大越会把真实小额偏差淹没成「变动严重虚高」的误报。与上方「授予增加」\n  // 重置对称:归零瞬间重置基准,从零余额起继续对账。\n  if (prevRef.granted > 0.009 && snap.granted <= 0.009) {\n    return { ref: snap, event: { kind: 'structure-reset' } }\n  }\n  const isCny = snap.currency.toUpperCase() === 'CNY'\n  const fallbackRate = isCny ? 7.2 : 1\n  const configuredRate = Number(options?.exchangeRate)\n  const exchangeRate = Number.isFinite(configuredRate) && configuredRate > 0 ? configuredRate : fallbackRate\n  const spent = prevRef.total - snap.total\n  const spentUsd = isCny ? spent / exchangeRate : spent\n  // 余额未减少:无法对账(可能整天走订阅扣费),静默。\n  if (spent <= 0.009) return { ref: prevRef, event: { kind: 'flat' } }\n  todayCost -= prevRef.ledgerCost\n  const dev = Math.abs(spentUsd - todayCost)\n  const threshold = Math.max(0.3, 0.15 * Math.max(spentUsd, todayCost))\n  if (dev > threshold) {\n    // 赠送余额部分减少(issue #302):#89 只覆盖「归零」;赠送桶部分到期/回收时,总额减量\n    // 全部落在赠送桶、充值桶不变,本地消费却远低于该减量——整块差额不是消费,报 drift 会\n    // 把到期金额当成「变动虚高」。仅当下面三个条件同时成立才降级(重置基准 + 一次性说明):\n    //   ① 减量可完全由赠送桶下降解释(充值桶没有实质减少,总额减量不超过赠送减量);\n    //   ② 同期本地官方渠道费用(含外部来源)最多只能解释减量的 1/4;\n    //   ③ 原本会触发 drift(dev 超既有阈值)——不改变阈值内已有的 ok/flat 判定。\n    // 本地费用能解释相当比例(>1/4)时仍按真实 drift 上报,避免吞掉漏记消费。\n    const grantedDrop = prevRef.granted - snap.granted\n    const toppedDrop = prevRef.topped - snap.topped\n    const grantedOnlyDecrease = Number.isFinite(prevRef.granted) && Number.isFinite(prevRef.topped)\n      && grantedDrop > 0.009\n      && toppedDrop <= 0.009\n      && spent <= grantedDrop + 0.009\n      && todayCost <= spentUsd * GRANTED_RELEASE_MAX_LOCAL_RATIO\n    if (grantedOnlyDecrease) return { ref: snap, event: { kind: 'granted-release', spent, spentCurrency: snap.currency, spentUsd, todayCost } }\n    return { ref: prevRef, event: { kind: 'drift', spent, spentCurrency: snap.currency, spentUsd, todayCost } }\n  }\n  // ok/drift 都保留当日首次基准,后续拉取继续与早间基线比对。\n  return { ref: prevRef, event: { kind: 'ok', spent, spentCurrency: snap.currency, spentUsd, todayCost } }\n}\n\n/**\n * 从官方余额接口的 balance_infos 中挑选要展示的条目(issues #24/#25)。\n *\n * 多币种账号同时返回 CNY/USD 两条,且实测两条的排列顺序每次请求不稳定——\n * 固定取首条会在 USD 排前时读到 0.00,余额在正确值与 0 之间跳变。挑选规则:\n *  - 优先取「有余额」的条目;同有余额时优先 CNY(开放平台主币种,确定性优先);\n *  - 全部为零时优先 CNY(未充值/新账号,保证不随返回顺序跳变);\n *  - 无 CNY 条目时兜底首条(单币种账号行为与旧版一致)。\n * @param infos - balance_infos 数组(元素含 currency / total_balance 等官方字段)。\n * @returns 选中的条目,或 undefined(无有效条目,调用方按缺 balance_infos 报错)。\n */\nexport function pickBalanceInfo(infos) {\n  const list = Array.isArray(infos) ? infos.filter(entry => entry !== null && typeof entry === 'object') : []\n  const positive = list.filter(entry => Number(entry.total_balance) > 0)\n  const cnyFirst = entries => entries.find(entry => String(entry.currency).toUpperCase() === 'CNY')\n  return cnyFirst(positive) ?? positive[0] ?? cnyFirst(list) ?? list[0]\n}\n"
    },
    {
      "path": "lib/usage-dedup.js",
      "content": "/**\n * usage 指纹窗口去重(issue #76,统一收口 #48 / #70)。\n *\n * 背景:modlens 等包装路由插件会把同一份 usage 经上游 llm.stream 再转发一次\n * (#48 / #70)。#70 时代的修复是对包装层 provider 的 usage「一律丢弃、只记\n * 上游真实流」——但当整条链路都是包装型 id 时(如 modlens 转售路由\n * modlens-go-ds4f,上游不再产生独立的非包装流),唯一到达的 usage 也被丢弃,\n * 整单漏计(#76 实测:会话日志有 usage,账本 sessions=0,今日费用恒 ¥0)。\n *\n * 修复:改用指纹窗口去重。同一会话内,(上游 provider, model, 五桶逐位指纹) 相同的样本在\n * 窗口期(默认 10s,包装层与上游两次分发的间隔量级)内只入账一次:\n *  - 非包装样本只查「已入账的改挂样本」:命中 = 包装层先到的转发对,跳过;\n *    合法的两次同量普通调用互不去重(与旧行为一致,零回归)。\n *  - 包装样本先经 wrapperUpstreamProvider 改挂上游 id(与 modlens-wrapper-\n *    dedup-v1 历史清洗同口径),再查两个集合:命中任一即跳过(上游先到 /\n *    包装层重复分发)。\n * 两种到达顺序都恰好入账一次,且都挂在用户可见请求的语义上游 id 下。\n *\n * 代价:同会话同模型五桶逐位相同、间隔小于窗口的两次包装链调用会被合并为\n * 一次(流式 usage 含缓存读数,逐位相同概率可忽略;#48/#70 的观察也证实\n * 转发对恰是逐位相同)。窗口过期后照常入账。\n */\n\nimport { isWrapperProviderId, wrapperUpstreamProvider } from './pricing.js'\n\n/** 与投影折叠(lib/index.js)/历史回放(lib/backfill.js)共用的窗口宽度。 */\nexport const USAGE_DEDUP_WINDOW_MS = 10_000\n\n/**\n * (上游 provider, model, 五桶) 指纹:逐位精确比较。包装转发的双份 usage 实测逐位相同\n * (issue #48 报告「同 token 逐位相同 ×3」),无需模糊。\n */\nexport function usageFingerprint(model, buckets, provider) {\n  return JSON.stringify([\n    String(provider ?? '').trim().toLowerCase().replace(/^llm-/, ''),\n    String(model ?? ''),\n    buckets?.input ?? 0,\n    buckets?.output ?? 0,\n    buckets?.cacheRead ?? 0,\n    buckets?.cacheWrite ?? 0,\n    buckets?.reasoning ?? 0,\n  ])\n}\n\n/**\n * 创建账本入账路径(llm/stream 钩子)用的去重器。\n * @param {{ windowMs?: number, now?: () => number, maxEntries?: number }} [options]\n *   - windowMs:指纹窗口宽度,默认 USAGE_DEDUP_WINDOW_MS。\n *   - now:时钟源(atMs 缺失/非法时兜底),测试注入用。\n *   - maxEntries:单会话单集合的容量上限(异常高频场景的内存护栏)。\n */\nexport function createUsageDeduper({ windowMs = USAGE_DEDUP_WINDOW_MS, now = Date.now, maxEntries = 128 } = {}) {\n  // key:sessionId('' = 无会话的辅助调用)→ { plain, remapped }。\n  // plain:非包装样本指纹 → 时刻;remapped:包装层改挂样本指纹 → 时刻。\n  const sessions = new Map()\n  // Request timestamps may arrive out of order; cleanup uses a separate arrival clock.\n  const retentionMs = Math.max(windowMs, 5 * 60_000)\n\n  const sweep = (book, clock) => {\n    for (const [fp, observations] of book) {\n      const recent = observations.filter(row => clock - row.seen <= retentionMs)\n      if (recent.length) book.set(fp, recent)\n      else book.delete(fp)\n    }\n  }\n\n  // 不再访问的会话也要清理过期指纹。登记本次调用后再裁剪，避免把尚未\n  // 写入指纹的新会话当作空条目删除，使超过阈值后的转发对重复入账。\n  let nextPruneAt = 0\n  const pruneIfNeeded = t => {\n    if (sessions.size <= 1024) return\n    if (t < nextPruneAt) return\n    nextPruneAt = t + windowMs\n    for (const [key, entry] of sessions) {\n      sweep(entry.plain, t)\n      sweep(entry.remapped, t)\n      if (entry.plain.size === 0 && entry.remapped.size === 0) sessions.delete(key)\n    }\n  }\n\n  return {\n    /**\n     * 判定一条 usage 是否入账,并登记指纹。\n     * @param {string} sessionId - 会话 id(可为空串/undefined)。\n     * @param {string} model - 模型 id。\n     * @param {string} provider - 原始 provider(可为包装层 id;非字符串视为空)。\n     * @param {object} buckets - 五桶 { input, output, cacheRead, cacheWrite, reasoning }。\n     * @param {number} atMs - 请求发起时刻(epoch ms)。\n     * @returns {string | null} 应入账的 provider id(包装层已改挂上游);\n     *   null = 窗口内判定为重复转发,调用方应跳过入账。\n     */\n    admit(sessionId, model, provider, buckets, atMs) {\n      const prov = typeof provider === 'string' ? provider : ''\n      const wrapped = isWrapperProviderId(prov)\n      const effective = wrapped ? (wrapperUpstreamProvider(prov) ?? prov) : prov\n      const key = typeof sessionId === 'string' && sessionId.length > 0 ? sessionId : ''\n      const t = Number.isFinite(atMs) && atMs > 0 ? atMs : now()\n      const clock = now()\n      const fp = usageFingerprint(model, buckets, effective)\n      let entry = sessions.get(key)\n      if (entry === undefined) {\n        entry = { plain: new Map(), remapped: new Map() }\n        sessions.set(key, entry)\n      }\n      sweep(entry.plain, clock)\n      sweep(entry.remapped, clock)\n      const book = wrapped ? entry.remapped : entry.plain\n      // 包装样本与普通样本、改挂样本都互斥;普通样本只与改挂样本互斥。\n      const matches = source => source.get(fp)?.some(row => Math.abs(t - row.at) <= windowMs) === true\n      if (wrapped ? (matches(entry.plain) || matches(entry.remapped)) : matches(entry.remapped)) {\n        return null\n      }\n      book.set(fp, [...(book.get(fp) ?? []), { at: t, seen: clock }].slice(-maxEntries))\n      sessions.delete(key); sessions.set(key, entry)\n      pruneIfNeeded(clock)\n      while (sessions.size > 4096) sessions.delete(sessions.keys().next().value)\n      while ([...book.values()].reduce((sum, rows) => sum + rows.length, 0) > maxEntries) {\n        // 容量护栏:淘汰最旧条目(窗口语义只关心最近的转发对)。\n        let oldestFp = null\n        let oldestAt = Infinity\n        for (const [candidateFp, observations] of book) {\n          const at = observations[0].seen\n          if (at < oldestAt) { oldestAt = at; oldestFp = candidateFp }\n        }\n        if (oldestFp !== null) {\n          const rows = book.get(oldestFp)\n          rows.shift()\n          if (!rows.length) book.delete(oldestFp)\n        }\n      }\n      return effective\n    },\n  }\n}\n"
    },
